"use client";
import axiosInstance from "@/api/axiosInstance";
import React, { useEffect, useState } from "react";

export default function Content() {
    const [data, setData] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        const fetchData = async () => {
            try {
                const response = await axiosInstance.get("/api/content");
                setData(response.data);
            } catch (error) {
                setError(error);
            } finally {
                setLoading(false);
            }
        };

        fetchData();
    }, []);

    if (loading) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-gray-100">
                <div className="text-gray-700 text-lg font-medium">Loading...</div>
            </div>
        );
    }

    if (error) {
        return (
            <div className="min-h-screen flex items-center justify-center bg-red-100">
                <div className="text-red-600 text-lg font-medium">Error: {error.message}</div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-gray-50 py-10 px-6">
            <div className="max-w-6xl mx-auto">
                <h1 className="text-3xl font-bold text-gray-800 mb-6 text-center">Latest Content</h1>

                <div className="grid gap-6 grid-cols-1 sm:grid-cols-2 lg:grid-cols-3">
                    {data && data.map((item) => (
                        <div key={item._id} className="bg-white shadow-lg rounded-xl p-6 hover:shadow-xl transition duration-300">
                            <h2 className="text-xl font-semibold text-gray-800 mb-2">{item.title}</h2>
                            <p className="text-gray-600 mb-3">{item.description}</p>
                            <p className="text-gray-700 text-sm">{item.body}</p>
                            <p className="text-sm text-gray-500 mt-4">Posted by: <span className="font-medium text-gray-700">{item.username}</span></p>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
}
